//--------------------------------------------------------------------------//

void dei_ss_trunk_close( void )
{	
	if( get_ss_arm() && !get_ss_trigger() && get_ss_trunk_bypass()) {
			set_ss_trunk_bypass( FALSE );
			if( get_ss_door_bypass() || get_ss_hood_bypass() ) {            
			dei_led_flash( DEI_SS_LED_ZONE_BYPASS , LED_ENABLE);								
      }
    else {
      dei_led_flash( DEI_LED_ARM , LED_ENABLE); 
      }	
		}
	
	set_ss_trunk_bypass( FALSE );
}


//--------------------------------------------------------------------------//

void dei_ss_trunk_open( void )
{
	if( get_zone_bypass_status() || get_ss_trunk_bypass()) return ; 
	
	if( get_ss_arm() && !get_ss_valet() && !get_ss_trunk_release()  )
	{
#ifdef PLATFORM_933		
		if((pop_trunk_state!=POP_TRUNK_STATE_WAIT10MIN)&&(pop_trunk_state!=POP_TRUNK_STATE_WAIT_CLOSE_2))	{
			dei_ss_trigger_start( DEI_SS_TRIGGER_ZONE_TRUNK );
		}
#else
		dei_ss_trigger_start( DEI_SS_TRIGGER_ZONE_TRUNK ) ; 
#endif		
	}
}	

